{
  "name": "opencode-auto-qcgates",
  "version": "1.9.0",
  "description": "Test execution, baseline management, and threshold evaluation for quality gates.",
  "type": "module",
  "module": "index.ts",
  "exports": {
    ".": "./index.ts",
    "./server": "./index.ts"
  },
  "sideEffects": false,
  "content": "code",
  "engines": {
    "bun": ">=1.0.0"
  },
  "bin": {
    "opencode-auto-qcgates": "./src/cli.ts"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/Expert-Vision-Software/opencode-auto-qcgates.git"
  },
  "publisher": "Expert Vision Software",
  "author": "Expert Vision Support <support@expertvision.software>",
  "bugs": {
    "url": "https://github.com/Expert-Vision-Software/opencode-auto-qcgates/issues",
    "email": "support@expertvisionsoftware.com"
  },
  "files": [
    "index.ts",
    "src",
    "skills",
    "commands",
    "manifest.json"
  ],
  "scripts": {
    "check": "tsc --noEmit",
    "test": "bun test",
    "prepublishOnly": "bun run check && bun test"
  },
  "keywords": ["opencode", "testing", "baselining", "quality-gates"],
  "license": "MIT",
  "dependencies": {
    "@inquirer/prompts": "^8.3.0",
    "@opencode/plugin": "latest",
    "effect": "4.0.0-rc.112"
  },
  "devDependencies": {
    "@types/bun": "^1.4.2",
    "@types/node": "^26.6.2",
    "js-yaml": "^5.3.0",
    "typescript": "^7.0.2"
  }
}

{
  "$schema": "https://opencode.ai/config.json",
  "plugin": [
    "opencode-architect@latest"
  ]
}
